    int n = nums.length;
    int mid = n / 2;
    int[] result = new int[n];

    for (int i = 0; i < n; i++) {
        if (i < mid) {
            result[i * 2] = nums[i];
        } else {
            result[(i - mid) * 2 + 1] = nums[i];
        }
    }

    return result;
}
```

